const signup = `-- name: Signup :one

SELECT tenant_id::uuid, user_id::uuid FROM signup($1, $2, $3, $4)
`

type SignupParams struct {
	Email        string `json:"email"`
	PasswordHash string `json:"password_hash"`
	TenantName   string `json:"tenant_name"`
	Name         string `json:"name"`
}

type SignupRow struct {
	TenantID pgtype.UUID `json:"tenant_id"`
	UserID   pgtype.UUID `json:"user_id"`
}

// RLS applies the tenant filter from app.tenant_id. Tables a user also sees across tenants (tenants, tenant_members,
// users, sessions) need an explicit filter: with app.user_id set, RLS alone returns more than one tenant's rows.
func (q *Queries) Signup(ctx context.Context, arg SignupParams) (SignupRow, error) {
	row := q.db.QueryRow(ctx, signup,
		arg.Email,
		arg.PasswordHash,
		arg.TenantName,
		arg.Name,
	)
	var i SignupRow
	err := row.Scan(&i.TenantID, &i.UserID)
	return i, err
}

